const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const shanghaiPoint = ee.Geometry.Point([121.4737, 31.2304]);
    const dateStart = '2013-08-07';
    const dateEnd = '2013-08-08';

    // 2. Data Acquisition & Check
    // Use MODIS daily Land Surface Temperature data.
    const modisLST = ee.ImageCollection('MODIS/061/MOD11A1')
        .filterDate(dateStart, dateEnd)
        .filterBounds(shanghaiPoint);

    const imageCount = modisLST.size().getInfo();
    if (imageCount === 0) {
        console.log('Evidence: No MODIS images found for the specified date and location.');
        console.log('A: No');
        return;
    }

    // 3. Processing
    // Get the first (and likely only) image.
    const image = ee.Image(modisLST.first());

    // Select the daytime LST band and the Quality Control band.
    const lstDay = image.select('LST_Day_1km');
    const qcDay = image.select('QC_Day');

    // Create a mask for good quality pixels.
    // According to MOD11A1 documentation, bits 0-1 of QC_Day == 00 means good quality.
    const qualityMask = qcDay.bitwiseAnd(0b11).eq(0);

    // Apply the quality mask and convert temperature from scaled Kelvin to Celsius.
    // Scale factor is 0.02 for this product.
    const lstCelsius = lstDay.updateMask(qualityMask)
        .multiply(0.02)
        .subtract(273.15);

    // 4. Calculation
    // Check pixel count first to avoid C2 error.
    const pixelCount = lstCelsius.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: shanghaiPoint,
        scale: 1000,
    }).get('LST_Day_1km').getInfo();

    if (pixelCount === null || pixelCount === 0) {
        console.log(`Evidence: Image found, but no valid (cloud-free) pixels for Shanghai.`);
        console.log(`Valid Pixels: ${pixelCount}`);
        console.log('C2: No Valid Pixels');
        return;
    }

    // Calculate the mean temperature for the single point.
    const tempInfo = lstCelsius.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: shanghaiPoint,
        scale: 1000,
    }).get('LST_Day_1km');

    const temperature = tempInfo.getInfo();

    // 5. Validation & Final Answer
    if (temperature === null) {
        console.log('Evidence: Failed to calculate temperature. Result was null.');
        console.log('C3: Calculation Failure');
        return;
    }

    console.log(`Evidence: Found ${imageCount} image(s) for the date.`);
    console.log(`Evidence: Land Surface Temperature on 2013-08-07 was ${temperature.toFixed(2)} °C.`);
    console.log(`Evidence: This is based on ${pixelCount} valid pixel(s).`);

    if (temperature > 39) {
        console.log('A: Yes');
    } else {
        console.log('B: No');
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or analysis.');
        console.error(e);
        console.log('D');
    }
}

initEE();
